package com.bank.qa.login;

// Outcome of a login attempt with a deliberately generic message.
class AuthResult {
    enum Status { SUCCESS, INVALID_CREDENTIALS, VALIDATION_ERROR, LOCKED, BLOCKED_INPUT }
    private final Status status;
    private final String message; // generic, non-leaky
    AuthResult(Status status, String message) { this.status = status; this.message = message; }
    Status getStatus() { return status; }
    String getMessage() { return message; }
}
