package com.bank.qa.login;

import java.util.logging.Logger;

// Each method is a documented test case; returns true if expectation met.
class LoginTestSuite {
    private static final Logger log = Logger.getLogger(LoginTestSuite.class.getName());
    private final LoginService svc = new LoginService();

    private void check(String name, boolean passed) {
        log.info((passed ? "PASS " : "FAIL ") + name);
    }

    void runAll() {
        // POSITIVE
        check("TC1 valid credentials succeed",
            svc.login("rajesh", "Pass@123").getStatus() == AuthResult.Status.SUCCESS);
        // NEGATIVE
        check("TC2 valid user wrong password -> generic",
            new LoginService().login("rajesh", "wrong").getStatus() == AuthResult.Status.INVALID_CREDENTIALS);
        check("TC3 unknown user -> SAME generic (no enumeration)",
            new LoginService().login("ghost", "x").getStatus() == AuthResult.Status.INVALID_CREDENTIALS);
        check("TC4 empty fields -> validation error",
            svc.login("", "").getStatus() == AuthResult.Status.VALIDATION_ERROR);
        // SECURITY: lockout boundary
        LoginService lock = new LoginService();
        for (int i = 1; i <= 4; i++) lock.login("priya", "bad");
        boolean fifthLocks = lock.login("priya", "bad").getStatus() == AuthResult.Status.LOCKED;
        check("TC5 lockout on 5th failed attempt", fifthLocks);
        check("TC6 correct password refused while locked",
            lock.login("priya", "Secure#99").getStatus() == AuthResult.Status.LOCKED);
        // SECURITY: injection / XSS
        check("TC7 SQL injection blocked",
            svc.login("rajesh' OR 1=1 --", "x").getStatus() == AuthResult.Status.BLOCKED_INPUT);
        check("TC8 XSS payload blocked",
            svc.login("<script>alert(1)</script>", "x").getStatus() == AuthResult.Status.BLOCKED_INPUT);
        // UI / SESSION properties
        check("TC9 password is masked", svc.isPasswordMasked());
        check("TC10 session timeout configured (10 min)", svc.sessionTimeoutMinutes() == 10);
    }
}
