package com.bank.qa.login;

import java.util.logging.*;

public class LoginTestDemo {
    private static final Logger log = Logger.getLogger(LoginTestDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new LoginLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info("=== Login page test suite (beyond happy path) ===");
        new LoginTestSuite().runAll();
        log.info("Remaining manual/E2E cases: remember-me cookie, logout invalidation, "
            + "password reset single-use link, browser matrix, accessibility (labels/ARIA/contrast).");
    }
}

